CREATE OR REPLACE FUNCTION public.org_audit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v jsonb;oldv jsonb;eid uuid;BEGIN v:=CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;oldv:=CASE WHEN TG_OP='UPDATE' THEN to_jsonb(OLD) ELSE '{}'::jsonb END;IF TG_TABLE_NAME<>'org_settings' THEN eid:=coalesce((v->>'id')::uuid,(v->>'person_id')::uuid);END IF;INSERT INTO activity_log(user_id,action,entity_type,entity_id,details) VALUES(auth.uid(),lower(TG_OP),TG_TABLE_NAME,eid,jsonb_build_object('before',oldv-ARRAY['email','privacy_notice'],'after',v-ARRAY['email','privacy_notice']));IF TG_OP='DELETE' THEN RETURN OLD;END IF;RETURN NEW;END $$;
CREATE TRIGGER audit_settings AFTER INSERT OR UPDATE ON org_settings FOR EACH ROW EXECUTE FUNCTION org_audit();
CREATE OR REPLACE FUNCTION public.log_workspace_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o jsonb;n jsonb;actor uuid;BEGIN IF TG_OP<>'INSERT' THEN o:=to_jsonb(OLD);END IF;IF TG_OP<>'DELETE' THEN n:=to_jsonb(NEW);END IF;actor:=auth.uid();IF TG_TABLE_NAME='assessment_attempts' THEN o:=o-ARRAY['answers','token_hash','name','accommodation_request','alternate_format','privacy_notice'];n:=n-ARRAY['answers','token_hash','name','accommodation_request','alternate_format','privacy_notice'];END IF;INSERT INTO activity_log(user_id,action,entity_type,entity_id,details) VALUES(actor,lower(TG_OP),TG_TABLE_NAME,coalesce((n->>'id')::uuid,(o->>'id')::uuid,(n->>'competency_id')::uuid,(o->>'competency_id')::uuid,(n->>'conflict_id')::uuid,(o->>'conflict_id')::uuid,(n->>'user_id')::uuid,(o->>'user_id')::uuid),jsonb_build_object('before',o,'after',n));IF TG_OP='DELETE' THEN RETURN OLD;END IF;RETURN NEW;END $$;
CREATE POLICY audit_admin_gate ON activity_log AS RESTRICTIVE FOR SELECT TO authenticated USING(org_can('people'));
CREATE FUNCTION public.org_session() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p org_people;rs jsonb;ass jsonb;BEGIN SELECT * INTO p FROM org_people WHERE user_id=auth.uid();IF p.id IS NULL THEN RETURN jsonb_build_object('person',NULL,'assignments','[]');END IF;IF p.status='active' THEN UPDATE org_people SET last_active=now() WHERE id=p.id AND (last_active IS NULL OR last_active<now()-interval '15 minutes');END IF;SELECT coalesce(jsonb_agg(role),'[]') INTO rs FROM org_person_roles WHERE person_id=p.id;SELECT coalesce(jsonb_agg(to_jsonb(a)),'[]') INTO ass FROM org_assignments a WHERE person_id=p.id;RETURN jsonb_build_object('person',to_jsonb(p)||jsonb_build_object('roles',rs),'assignments',ass);END $$;
CREATE FUNCTION public.org_accept_invitation(inv uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i org_invitations;p org_people;mail text;BEGIN PERFORM pg_advisory_xact_lock(991112026);IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in to accept';END IF;SELECT * INTO i FROM org_invitations WHERE id=inv FOR UPDATE;SELECT * INTO p FROM org_people WHERE id=i.person_id;mail:=lower(auth.jwt()->>'email');IF i.id IS NULL OR i.revoked OR i.accepted_at IS NOT NULL OR i.expires_at<now() OR p.status<>'invited' OR lower(p.email) IS DISTINCT FROM mail THEN RAISE EXCEPTION 'Invitation unavailable for this account';END IF;IF p.user_id IS NOT NULL AND p.user_id<>auth.uid() THEN RAISE EXCEPTION 'Invitation belongs to another account';END IF;UPDATE org_people SET user_id=auth.uid(),status='active',last_active=now() WHERE id=p.id;UPDATE org_invitations SET accepted_at=now() WHERE id=inv;RETURN true;END $$;
CREATE FUNCTION public.org_blind_work(rid uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT org_can('score',rid) THEN RETURN '[]';END IF;RETURN (SELECT coalesce(jsonb_agg(jsonb_build_object('attempt_id',a.id,'candidate_id','C-'||left(a.id::text,8),'item',i.value-ARRAY['correct','key','explanation','approvals'],'response',a.answers->>ra.item_id,'status',a.status,'my_ratings',(SELECT v FROM jsonb_array_elements(a.raters) v WHERE v->>'item_id'=ra.item_id AND v->>'user_id'=auth.uid()::text))),'[]') FROM assessment_rater_assignments ra JOIN org_people p ON p.id=ra.person_id JOIN assessment_attempts a ON a.id=ra.attempt_id JOIN assessment_batteries b ON b.id=a.battery_id CROSS JOIN LATERAL jsonb_array_elements(b.payload->'items') i WHERE a.battery_id=rid AND a.status IN ('submitted','scored') AND a.purged_at IS NULL AND i.value->>'id'=ra.item_id AND i.value->>'method'='work_sample' AND (p.user_id=auth.uid() OR org_has_role(auth.uid(),'admin')));END $$;
CREATE FUNCTION public.org_fairness_data(rid uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT org_can('fairness',rid) THEN RAISE EXCEPTION 'Analyst access required';END IF;RETURN jsonb_build_object('groups',(SELECT coalesce(jsonb_agg(jsonb_build_object('attempt_id',a.id,'group_label',d.group_label)),'[]') FROM assessment_demographics d JOIN assessment_attempts a ON a.id=d.attempt_id WHERE a.battery_id=rid),'attempts',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',a.id,'battery_id',a.battery_id,'name','C-'||left(a.id::text,8),'status',a.status,'scores',a.scores,'answers','{}'::jsonb,'raters','[]'::jsonb,'reconciliations','{}'::jsonb,'created_at',a.created_at,'submitted_at',a.submitted_at)),'[]') FROM assessment_attempts a WHERE a.battery_id=rid AND a.purged_at IS NULL));END $$;
CREATE FUNCTION public.org_score_snapshot(aid uuid,item text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a assessment_attempts;b assessment_batteries;BEGIN SELECT * INTO a FROM assessment_attempts WHERE id=aid;IF a.id IS NULL OR NOT org_can('score',a.battery_id) THEN RAISE EXCEPTION 'Assigned Rater required';END IF;IF NOT org_has_role(auth.uid(),'admin') AND (item IS NULL OR NOT EXISTS(SELECT 1 FROM assessment_rater_assignments r JOIN org_people p ON p.id=r.person_id WHERE r.attempt_id=aid AND r.item_id=item AND p.user_id=auth.uid())) THEN RAISE EXCEPTION 'Work sample assignment required';END IF;SELECT * INTO b FROM assessment_batteries WHERE id=a.battery_id;RETURN jsonb_build_object('attempt',to_jsonb(a)-ARRAY['name','token_hash','accommodation_request','alternate_format','privacy_notice'],'battery',b.payload);END $$;
CREATE FUNCTION public.org_store_score(aid uuid,expected jsonb,rs jsonb,recs jsonb,sc jsonb,st text,item text DEFAULT NULL) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a assessment_attempts;oldothers jsonb;newothers jsonb;v jsonb;BEGIN PERFORM pg_advisory_xact_lock(811112026);SELECT * INTO a FROM assessment_attempts WHERE id=aid FOR UPDATE;IF NOT org_can('score',a.battery_id) THEN RAISE EXCEPTION 'Assigned Rater required';END IF;IF a.status NOT IN ('submitted','scored') OR a.raters IS DISTINCT FROM expected THEN RAISE EXCEPTION 'Scoring changed; refresh and retry';END IF;IF NOT org_has_role(auth.uid(),'admin') THEN IF NOT EXISTS(SELECT 1 FROM assessment_rater_assignments r JOIN org_people p ON p.id=r.person_id WHERE r.attempt_id=aid AND r.item_id=item AND p.user_id=auth.uid()) THEN RAISE EXCEPTION 'Work sample assignment required';END IF;IF recs<>a.reconciliations THEN RAISE EXCEPTION 'Only Admin can reconcile';END IF;SELECT coalesce(jsonb_agg(value ORDER BY value::text),'[]') INTO oldothers FROM jsonb_array_elements(a.raters) WHERE value->>'user_id'<>auth.uid()::text OR value->>'item_id'<>item;SELECT coalesce(jsonb_agg(value ORDER BY value::text),'[]') INTO newothers FROM jsonb_array_elements(rs) WHERE value->>'user_id'<>auth.uid()::text OR value->>'item_id'<>item;IF oldothers<>newothers THEN RAISE EXCEPTION 'Other rater scores immutable';END IF;END IF;UPDATE assessment_attempts SET raters=rs,reconciliations=recs,scores=sc,status=st WHERE id=aid;RETURN true;END $$;
REVOKE ALL ON FUNCTION org_session(),org_accept_invitation(uuid),org_blind_work(uuid),org_fairness_data(uuid),org_score_snapshot(uuid,text),org_store_score(uuid,jsonb,jsonb,jsonb,jsonb,text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION org_session(),org_accept_invitation(uuid),org_blind_work(uuid),org_fairness_data(uuid),org_score_snapshot(uuid,text) TO authenticated;
GRANT EXECUTE ON FUNCTION org_store_score(uuid,jsonb,jsonb,jsonb,jsonb,text,text) TO service_role;
CREATE FUNCTION public.org_review_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR coalesce(auth.role(),'')='service_role' THEN RETURN NEW;END IF;IF TG_OP='UPDATE' THEN IF NEW.status IS DISTINCT FROM OLD.status AND NEW.status IN ('approved','rejected') THEN IF OLD.status<>'in_review' OR NOT org_can('approve',NEW.id) THEN RAISE EXCEPTION 'HR decision requires submitted battery';END IF;END IF;IF NEW.analysis_status IS DISTINCT FROM OLD.analysis_status AND NEW.analysis_status IN ('approved','rejected') THEN IF OLD.analysis_status<>'in_review' OR NOT org_can('approve',NEW.id) THEN RAISE EXCEPTION 'HR decision requires submitted analysis';END IF;END IF;IF NEW.status<>'approved' AND (NEW.approved_by IS DISTINCT FROM OLD.approved_by OR NEW.approved_at IS DISTINCT FROM OLD.approved_at) THEN RAISE EXCEPTION 'Approval metadata protected';END IF;END IF;RETURN NEW;END $$;
CREATE TRIGGER org_review_guard BEFORE UPDATE ON assessment_batteries FOR EACH ROW EXECUTE FUNCTION org_review_guard();
CREATE FUNCTION public.org_retention_cleanup() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE months integer;n integer;BEGIN PERFORM pg_advisory_xact_lock(811112026);SELECT retention_months INTO months FROM org_settings WHERE id;months:=coalesce(months,12);DELETE FROM assessment_demographics WHERE attempt_id IN(SELECT id FROM assessment_attempts WHERE created_at<now()-make_interval(months=>months));DELETE FROM assessment_rater_assignments WHERE attempt_id IN(SELECT id FROM assessment_attempts WHERE created_at<now()-make_interval(months=>months));UPDATE assessment_attempts SET name='Removed under retention policy',answers='{}',raters='[]',reconciliations='{}',scores='{}',token_hash=NULL,revoked=true,accommodation_request='',alternate_format='',purged_at=now() WHERE created_at<now()-make_interval(months=>months) AND purged_at IS NULL;GET DIAGNOSTICS n=ROW_COUNT;RETURN n;END $$;
REVOKE ALL ON FUNCTION org_retention_cleanup() FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION org_retention_cleanup() TO service_role;